PREFIX vocab: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?employee ?name ?email ?phone WHERE {
  ?employee a vocab:Employee .
  FILTER NOT EXISTS {
    ?otherEmployee vocab:hasManager ?employee .
  }
  ?employee vocab:name ?name .
  OPTIONAL { ?employee vocab:email ?email . }
  OPTIONAL { ?employee vocab:phone ?phone . }
}
ORDER BY ?name

SELECT DISTINCT ?category ?minHardware ?minWeight ?maxHardware ?maxWeight WHERE {
  {
    SELECT DISTINCT ?category (MIN(?weight) AS ?minWeight) (MAX(?weight) AS ?maxWeight) WHERE {
      ?hardware a <http://ld.company.org/prod-vocab/Hardware> .
      ?hardware <http://ld.company.org/prod-vocab/hasCategory> ?category .
      ?hardware <http://ld.company.org/prod-vocab/weight_g> ?weight .
    }
    GROUP BY ?category
  }
  ?minHardware a <http://ld.company.org/prod-vocab/Hardware> ;
               <http://ld.company.org/prod-vocab/hasCategory> ?category ;
               <http://ld.company.org/prod-vocab/weight_g> ?minWeight .
  ?maxHardware a <http://ld.company.org/prod-vocab/Hardware> ;
               <http://ld.company.org/prod-vocab/hasCategory> ?category ;
               <http://ld.company.org/prod-vocab/weight_g> ?maxWeight .
}

PREFIX prod: <http://ld.company.org/prod-vocab/>

SELECT DISTINCT ?category (GROUP_CONCAT(DISTINCT ?lightestHardware; separator=",") AS ?lightestHardwares)
                (GROUP_CONCAT(DISTINCT ?heaviestHardware; separator=",") AS ?heaviestHardwares)
WHERE {
  # Subquery to get min and max weight per category
  {
    SELECT DISTINCT ?category (MIN(?weight) AS ?minWeight) (MAX(?weight) AS ?maxWeight) WHERE {
      ?hardware a prod:Hardware ;
                prod:weight_g ?weight ;
                prod:hasCategory ?category .
    }
    GROUP BY ?category
  }

  # Get hardware products matching the min and max weights per category
  OPTIONAL {
    ?lightestHardware a prod:Hardware ;
                      prod:weight_g ?minWeight ;
                      prod:hasCategory ?category .
  }

  OPTIONAL {
    ?heaviestHardware a prod:Hardware ;
                      prod:weight_g ?maxWeight ;
                      prod:hasCategory ?category .
  }
}
GROUP BY ?category

PREFIX prod: <http://ld.company.org/prod-vocab/>

